create or replace function private.verify_audit_chain(p_organization_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare r record; v_prev text:='GENESIS:'||p_organization_id::text; v_expected text; v_count int:=0; v_first uuid; v_last uuid; v_payload text; begin if not private.aios_is_org_member(p_organization_id) then raise exception 'not authorized' using errcode='42501'; end if; for r in select * from public.aios_audit_events where organization_id=p_organization_id order by created_at,id loop v_count=v_count+1; if v_first is null then v_first=r.id; end if; v_last=r.id; v_payload=jsonb_build_object('id',r.id,'organization_id',r.organization_id,'actor_user_id',r.actor_user_id,'actor_type',r.actor_type,'agent_id',r.agent_id,'mission_id',r.mission_id,'task_id',r.task_id,'invocation_id',r.invocation_id,'event_type',r.event_type,'previous_state',r.previous_state,'new_state',r.new_state,'tool_name',r.tool_name,'risk_level',r.risk_level,'arguments_hash',r.arguments_hash,'result_hash',r.result_hash,'approval_id',r.approval_id,'created_at',r.created_at,'metadata',r.metadata,'previous_event_hash',v_prev)::text||v_prev; v_expected=encode(extensions.digest(v_payload,'sha256'),'hex'); if r.previous_event_hash is distinct from v_prev or r.event_hash is distinct from v_expected then return jsonb_build_object('valid',false,'events_checked',v_count,'first_event',v_first,'last_event',r.id,'broken_event_id',r.id,'expected_hash',v_expected,'actual_hash',r.event_hash); end if; v_prev=r.event_hash; end loop; return jsonb_build_object('valid',true,'events_checked',v_count,'first_event',v_first,'last_event',v_last,'broken_event_id',null,'expected_hash',null,'actual_hash',null); end; $$;
